"""Read-only verification; migration entry disarmed after the authorized activation."""
import base64,gzip,json,pathlib,shlex,subprocess,time
source="import json,subprocess\ncode=\"\\nimport fs from 'node:fs';import path from 'node:path';\\nimport {config} from './src/config.ts';\\nconst root=path.join(config.dataDir,'_operator_backups','remaining-creators-v2-20261013');\\nconst read=f=>{try{return JSON.parse(fs.readFileSync(path.join(root,f),'utf8'))}catch{return null;}};\\nconst result=read('result.json'),failure=read('failure.json'),handover=read('handover.json');\\nconst fleet=JSON.parse(fs.readFileSync(path.join(config.dataDir,'_fleet.json'),'utf8'));\\nconst since=handover?Object.values(handover.switchedAt).sort()[0]:new Date().toISOString();\\nconst observations=[];\\nfor(const slug of Object.keys(fleet.girls)){\\n const file=path.join(config.logDir,slug,'requests.jsonl');let rows=[];\\n try{const fd=fs.openSync(file,'r'),size=fs.fstatSync(fd).size,offset=Math.max(0,size-200000),b=Buffer.alloc(size-offset);fs.readSync(fd,b,0,b.length,offset);fs.closeSync(fd);let lines=b.toString().split('\\\\n');if(offset)lines.shift();rows=lines.flatMap(l=>{try{return [JSON.parse(l)]}catch{return []}}).filter(r=>r.ts>=since);}catch{}\\n observations.push({slug,state:fleet.girls[slug].status,botUsername:fleet.girls[slug].botUsername,startedAt:fleet.girls[slug].startedAt,observedTurns:rows.length,turnStatuses:rows.reduce((a,r)=>{const k=r.status??'unspecified';a[k]=(a[k]??0)+1;return a;},{})});\\n}\\nconsole.log('V2_MIGRATION_READONLY '+JSON.stringify({at:new Date().toISOString(),fleetAt:fleet.at,result,failure,observations,pendingHandoverFiles:fs.existsSync(path.join(config.dataDir,'_handover'))?fs.readdirSync(path.join(config.dataDir,'_handover')).filter(x=>x.endsWith('.request.json')):[],operatorLock:fs.existsSync(path.join(root,'operation.lock')),messagesSent:0,productionWrites:0}));\\n\"\np=subprocess.run(['docker','exec','-i','twin-v2-dash-1','node','--import','tsx','--input-type=module'],input=code,text=True,capture_output=True,timeout=60)\nif p.returncode: raise RuntimeError(p.stderr[-800:])\nfor line in p.stdout.splitlines():\n if line.startswith('V2_MIGRATION_READONLY '):print(line,flush=True)\nprint(subprocess.check_output(['docker','stats','--no-stream','--format','{{.Name}} memory={{.MemUsage}} cpu={{.CPUPerc}}','twin-v2-bot-1','twin-v2-dash-1'],text=True),flush=True)\nfor name in ['twin-v2-bot-1','twin-v2-dash-1']:\n d=json.loads(subprocess.check_output(['docker','inspect',name],text=True))[0]\n print(json.dumps({'container':name,'running':d['State']['Running'],'image':d['Image'],'oom':d['State']['OOMKilled'],'restartCount':d['RestartCount']}),flush=True)\n"
packed=base64.b64encode(gzip.compress(source.encode())).decode()
host="import base64,gzip;exec(compile(gzip.decompress(base64.b64decode("+repr(packed)+")),'v2-remaining','exec'))"
params={'commands':['python3 -c '+shlex.quote(host)],'executionTimeout':['220']}
p=pathlib.Path('/tmp/v2-remaining.json');p.write_text(json.dumps(params))
cid=subprocess.check_output(['aws','ssm','send-command','--instance-ids','i-0584d283506f3f6be','--document-name','AWS-RunShellScript','--parameters','file://'+str(p),'--comment','Read-only post-migration verification','--query','Command.CommandId','--output','text'],text=True).strip()
print(json.dumps({'commandId':cid}),flush=True)
for _ in range(80):
 try:r=json.loads(subprocess.check_output(['aws','ssm','get-command-invocation','--command-id',cid,'--instance-id','i-0584d283506f3f6be','--output','json'],text=True,stderr=subprocess.DEVNULL))
 except subprocess.CalledProcessError:time.sleep(3);continue
 if r['Status'] in ['Success','Failed','Cancelled','TimedOut']:break
 time.sleep(3)
else:raise RuntimeError('Readiness check incomplete')
print(r.get('StandardOutputContent',''),flush=True)
if r['Status']!='Success':
 print(r.get('StandardErrorContent','')[-1200:],flush=True)
 raise RuntimeError('Readiness check failed')
